/* Bibliothèque : explorateur de compétences, pages de thème, collections et liste de tous les cours Nunya.
   Chargé à la première ouverture de la bibliothèque, hors du bundle principal ; library-explorer.js garde les données et les branchements. */
let api,esc,at,aLink,aPageHead,icon,getCourse,aPythonCourseCard,aLabel;
const resourceCard=r=>api.resourceCard(r);
function aSkillHub(){if(!api.skills())return `<p>${esc(at('load'))}</p>`;return aPageHead('skillsExplorer',at('skillsNote'))+`<div class="a-skill-grid">${api.skills().topics.map(t=>`<a class="a-skill-topic" href="#/bibliotheque/theme/${t.id}">${icon(t.icon)}<h2>${esc(t.title_fr)}</h2><span>${esc(at('showCourses'))} →</span></a>`).join('')}</div><details class="panel"><summary>${esc(at('providers'))}</summary><p>LearnFree · Khan Academy · Microsoft Learn · freeCodeCamp · OpenLearn</p><p>${esc(at('sourceCourseNote'))}</p><a href="https://www.classcentral.com/report/big-tech-free-courses/" target="_blank" rel="noopener">Class Central · ${esc(at('discoveryOnly'))} ↗</a></details>`}
function aSkillTopic(id){const t=api.skills()?.topics.find(t=>t.id===id);if(!t)return aPageHead('unknown');const external=api.skills().courses.filter(c=>c.topic===id),own=t.course_ids.map(id=>getCourse(id)).filter(Boolean);return aLink('#/bibliotheque/competences','back','back-link')+`<header class="a-page-head"><span class="eyebrow">${esc(at('skillsExplorer'))}</span><h1>${esc(t.title_fr)}</h1><p>${esc(at('sourceCourseNote'))}</p></header><section class="a-section"><h2>${esc(at('learnHere'))}</h2><div class="a-library-shelf">${own.map(c=>c.id==='python'?aPythonCourseCard():`<a href="#/parcours/cours-${c.id}" class="a-shelf-card"><span class="eyebrow">NUNYA · FR · ${c.duration} min</span><h3>${esc(c.title)}</h3><p>${esc(at('textOnly'))} · ${esc(at('free'))}</p><span>${esc(at('start'))} →</span></a>`).join('')}</div></section><section class="a-section"><h2>${esc(at('courseCollections'))}</h2><div class="a-collection-grid">${external.slice(api.collectionPage()*9,api.collectionPage()*9+9).map(aCollectionCard).join('')}</div>${external.length>9?`<div class="a-inline-actions"><button class="secondary" data-collection-page="prev" ${api.collectionPage()===0?'disabled':''}>${esc(at('previous'))}</button><span>${api.collectionPage()+1}/${Math.ceil(external.length/9)}</span><button class="secondary" data-collection-page="next" ${(api.collectionPage()+1)*9>=external.length?'disabled':''}>${esc(at('following'))}</button></div>`:''}</section>`}
function aCollectionCard(c){return `<a class="a-collection-card" href="#/collection/${c.id}"><div class="a-collection-art">${icon(c.provider==='Khan Academy'?'book':c.provider==='LearnFree'?'monitor':'compass')}<span>${esc(c.provider)}</span></div><div><span class="eyebrow">${esc(c.integration==='embedded'?'FR · '+c.resource_count+' '+at('step'):at('frenchCompanion'))}</span><h3>${esc(c.title_fr)}</h3><p>${esc(c.description_fr)}</p><small>${esc(at('free'))} · ${esc(c.language.includes('fr')?'Source FR':'Source EN · guide FR')}</small><span>${esc(at('openCollection'))} →</span></div></a>`}
function aCollectionView(){if(!api.collection())return `<p>${esc(at('load'))}</p>`;const c=api.collection().course,guide=c.guide_course_id&&c.guide_course_id!=='python'&&getCourse(c.guide_course_id),rows=api.collection().resources.filter(r=>api.collectionUnit()==='all'||r.u===api.collectionUnit());return aLink('#/bibliotheque/theme/'+c.topic,'back','back-link')+`<header class="a-path-hero"><span class="eyebrow">${esc(c.provider)} · ${esc(at('free'))}</span><h1>${esc(c.title_fr)}</h1><p>${esc(c.description_fr)}</p><small>${esc(c.language.includes('fr')?'Source FR':'Source EN · accompagnement Nunya FR')} · ${esc(at('sourceChecked'))} ${esc(c.last_checked)}</small>${c.guide_course_id==='python'?`<div class="a-hero-actions">${aLink('#/apprendre/python-bases','startFrench','primary')}</div>`:''}${guide?`<div class="a-hero-actions">${aLink('#/parcours/cours-'+guide.id,'startFrench','primary')}</div>`:''}</header>${c.video?`<section class="a-collection-video panel"><h2>${esc(at('optionalVideo'))} · ${c.video.language==='fr'?'FR':'EN'}</h2><p>${esc(at('videoLanguageNote'))}</p><div class="study-video" id="a-collection-player"><button class="study-play" data-collection-video="${c.video.id}" aria-label="${esc(at('optionalVideo'))}"><span aria-hidden="true">▷</span><strong>${esc(at('playHere'))}</strong><small>${esc(c.video.provider)}</small></button></div></section>`:''}${guide?`<section class="panel"><h2>${esc(at('frenchCompanion'))}</h2><p>${esc(at('companionHonesty'))}</p><ol class="a-step-list">${guide.lessons.map((l,i)=>`<li><a href="#/parcours/cours-${guide.id}/etape/${i}"><span>${i+1}</span><span>${esc(l.title)}<small>${esc(at('read'))} · ${esc(at('walk'))} · ${esc(at('practice'))}</small></span><span>→</span></a></li>`).join('')}</ol></section>`:`<section class="a-section"><h2>${esc(at('showSteps'))}</h2>${c.units?.length?`<label>Unité de la collection<select id="collection-unit"><option value="all">Toutes les unités · ${api.collection().resources.length} ressources</option>${c.units.map((u,i)=>`<option value="${i}" ${u===api.collectionUnit()?'selected':''}>${esc(u)} · ${api.collection().resources.filter(r=>r.u===u).length}</option>`).join('')}</select></label>`:''}<div class="resource-grid">${rows.slice(api.collectionPage()*9,api.collectionPage()*9+9).map(resourceCard).join('')}</div><div class="a-inline-actions"><button class="secondary" data-collection-page="prev" ${api.collectionPage()===0?'disabled':''}>${esc(at('previous'))}</button><span>${api.collectionPage()+1}/${Math.max(1,Math.ceil(rows.length/9))}</span><button class="secondary" data-collection-page="next" ${(api.collectionPage()+1)*9>=rows.length?'disabled':''}>${esc(at('following'))}</button></div></section>`}<details class="panel"><summary>${esc(at('sources'))}</summary><p>${esc(c.attribution)}</p><p>${esc(c.license)}</p><p>${esc(at('sourceCourseNote'))}</p><a href="${esc(c.url)}" target="_blank" rel="noopener">${esc(at('official'))}</a>${c.terms_url?` · <a href="${esc(c.terms_url)}" target="_blank" rel="noopener">${esc(at('terms'))}</a>`:''}</details>`}

/* Tous les cours Nunya, à lire librement sans suivre de programme : chaque cours s’ouvre seul. */
// Trois familles au lieu d’une vingtaine de catégories : la catégorie d’origine reste écrite sur chaque carte.
const aCodeFamily=new Set(['PROGRAMMATION','DÉVELOPPEMENT WEB','CULTURE NUMÉRIQUE','LOGIQUE & ALGORITHMES','BASES DE DONNÉES','OUTILS DU DÉVELOPPEUR','CYBERSÉCURITÉ','DONNÉES & STATISTIQUES']);
const aSchoolFamily=new Set(['MATHÉMATIQUES','SCIENCES & TECHNIQUES','BIOLOGIE & SANTÉ','TERMINALE · PRÉPARER LE BAC II','RÉVISION SCOLAIRE']);
function aCourseGroups(){
 const groups=[[aLabel('Programmation et numérique','Programming and digital skills'),[]],[aLabel('Révisions scolaires','School revision'),[]],[aLabel('Métiers et compétences pratiques','Careers and practical skills'),[]]];
 for(const c of api.courses()){if(c.category==='PARCOURS IMPORTÉ')continue;groups[aCodeFamily.has(c.category)?0:aSchoolFamily.has(c.category)?1:2][1].push(c)}
 return groups.filter(([,list])=>list.length);
}
const aCourseCount=groups=>groups.reduce((n,[,list])=>n+list.length,0);
const aSessions=k=>k+' '+(k>1?aLabel('séances','sessions'):aLabel('séance','session'));
function aCourseCard(c){return c.id==='python'?aPythonCourseCard():`<a class="a-shelf-card" href="#/parcours/cours-${esc(c.id)}"><span class="eyebrow">${esc(c.category||'NUNYA')} · ${Number(c.duration)||0} min</span><h3>${esc(c.title)}</h3><p>${esc(c.desc||'')}</p><span>${aSessions((c.lessons||[]).length)} · ${esc(at('start'))} →</span></a>`}
function aAllCourses(){const groups=aCourseGroups(),n=aCourseCount(groups);return aLink('#/bibliotheque','back','back-link')+`<header class="a-page-head"><span class="eyebrow">NUNYA · ${esc(at('library'))}</span><h1>${esc(aLabel('Tous les cours Nunya','All Nunya courses'))}</h1><p>${esc(aLabel(n+' cours à lire à ton rythme, sans programme imposé. Chaque cours s’ouvre seul et ta progression reste sur cet appareil.',n+' courses to read at your own pace, with no set programme. Each course opens on its own and your progress stays on this device.'))}</p></header>`+groups.map(([title,list])=>`<section class="a-section"><h2>${esc(title)} · ${list.length}</h2><div class="a-library-shelf">${list.map(aCourseCard).join('')}</div></section>`).join('')}
function aDecorateLibrary(html){const n=aCourseCount(aCourseGroups());return html.replace('<section class="a-library-search">',`<section class="a-skills-invite"><div><span class="eyebrow">${esc(at('skillsExplorer'))}</span><h2>${esc(at('chooseSkill'))}</h2><p>${esc(at('skillsNote'))}</p></div>${aLink('#/bibliotheque/competences','exploreSkills','primary')}</section><section class="a-skills-invite"><div><span class="eyebrow">${esc(aLabel('Lire librement','Read freely'))}</span><h2>${esc(aLabel('Tous les cours Nunya','All Nunya courses'))}</h2><p>${esc(aLabel(n+' cours à lire à ton rythme, sans programme ni test.',n+' courses to read at your own pace, with no programme or test.'))}</p></div><a class="primary" href="#/bibliotheque/cours">${esc(aLabel('Voir tous les cours','See all courses'))}</a></section><section class="a-library-search">`)}

export function init(a){
 api=a;({esc,at,aLink,aPageHead,icon,getCourse,aPythonCourseCard,aLabel}=a);
 return {hub:aSkillHub,topic:aSkillTopic,collection:aCollectionView,all:aAllCourses,decorate:aDecorateLibrary};
}
